///
/// Volume and pan are copied from every source track but the nest clip's
/// destination, whose copy gets `keeps_mix` false and so unity and centre:
/// the destination track still applies over the nest clip, and a fader
/// applied twice is not a fader applied once (where muting twice is muting
/// once, so mute copies from it too).
///
/// A compressor or limiter is never copied (spec §11 AU-150): a nest's own
/// tracks have none, and the destination's still apply over the nest clip.
fn nested_track(project: &mut Project, from: &Track, keeps_mix: bool) -> Track {
    Track {
        id: project.allocate_id(),
        name: from.name.clone(),
        hidden: from.hidden,
        muted: from.muted,
        locked: from.locked,
        solo: from.solo,
        matte: from.matte,
        volume: if keeps_mix { from.volume } else { 1.0 },
        pan: if keeps_mix { from.pan } else { 0.0 },
        compressor: None,
        limiter: None,
    }
}

impl Project {
    /// Collapses `clips` into one nest clip (spec §6).
    ///
    /// The clips keep their relative times — the earliest starts at 0 inside
    /// the nest — their relative track order, their props and their actions;
    /// the nest clip covers exactly the span they covered, on the front-most
    /// track any of them was on.
    ///
    /// An empty selection, and a selection of one clip that is already a
    /// nest (grouping a group alone changes nothing a user can see), are
    /// identities. A nest clip that would break the overlap rule against
    /// whatever was NOT selected is refused, in the rule's own sentence. `Err` on an unknown clip id or a selection
    /// that would put the project past the track cap.
    pub fn nest_clips(&self, clips: &[u32], name: Option<&str>) -> Result<Outcome, String> {
        // A linked partner goes in with its clip (spec §11 AU-91).
        let selected: Vec<Clip> = self
            .selected_clips(&self.with_links(clips)?)?
            .into_iter()
            .cloned()
            .collect::<Vec<_>>();
        if selected.is_empty() {
            return Ok(Outcome::Identity);
        }
        if selected.len() == 1 && matches!(selected[0].source, Source::Nest { .. }) {
            return Ok(Outcome::Identity);
        }
        // An adjustment clip grades the top level only (spec §11 GR-6).
        if let Some(found) = selected.iter().find(|c| is_adjustment(c)) {
            return Ok(Outcome::Refused(adjustment_cannot_nest(found.id)));
        }

        let earliest = selected.iter().map(|c| c.start).min().unwrap_or(0);
        let latest = selected.iter().map(clip_end).max().unwrap_or(0);
        if latest <= earliest {
            return Ok(Outcome::Identity);
        }

        // The source tracks, back-most first, so the nest's own stack keeps
        // the order the timeline had. `track_index` is the stack position;
        // a clip on a track that is not in `tracks` cannot exist (`validate`
        // refuses it) and is skipped rather than defended against twice.
        let mut sources: Vec<(usize, u32)> = Vec::new();
        for clip in &selected {
            if let Some(index) = self.track_index(clip.track) {
                if !sources.iter().any(|(_, id)| *id == clip.track) {
                    sources.push((index, clip.track));
                }
            }
        }
        sources.sort_unstable();
        // The front-most source track that is not a matte track is where
        // the nest clip goes (MT-5): a matte pair nested together must land
        // where its picture was drawn, not on the matte track, where the
        // whole nest would become a matte. The front-most when all are. The
        // nest's own tracks count toward `MAX_TRACKS` like any other
        // (`format::check_caps`), so a selection that would overrun the cap
        // is caught by `finish` rather than counted twice here.
        let drawn = sources
            .iter()
            .rev()
            .find(|(_, id)| self.track(*id).is_some_and(|t| t.matte.is_none()));
        let Some((_, front_track)) = drawn.or(sources.last()).copied() else {
            return Ok(Outcome::Identity);
        };

        let mut next = self.clone();
        let nest_id = next.allocate_id();
        let mut tracks: Vec<Track> = Vec::with_capacity(sources.len());
        let mut mapping: Vec<(u32, u32)> = Vec::with_capacity(sources.len());
        for (_, id) in &sources {
            let Some(source) = self.track(*id) else {
                continue;
            };
            let track = nested_track(&mut next, source, *id != front_track);
            mapping.push((*id, track.id));
            tracks.push(track);
        }
        // The carry rule (MT-5), one pass over the mapping: a nested track
        // stays a matte only when the nested track directly behind it is the
        // copy of its source's target. A matte nested without its target
        // draws inside the nest as an ordinary track (owner, O9).
        for index in 0..tracks.len() {
            let from = mapping.get(index).map(|(from, _)| *from);
            let behind = index
                .checked_sub(1)
                .and_then(|i| mapping.get(i))
                .map(|(from, _)| *from);
            let carried = from.and_then(|from| matte_target(&self.tracks, from));
            if carried.is_none() || carried != behind {
                if let Some(track) = tracks.get_mut(index) {
                    track.matte = crate::model::TrackMatte::None;
                }
            }
        }

        // The clips move WHOLE — ids, actions, transitions and all — so
        // nothing about them has to be re-minted or re-checked. Only their
        // container changes.
        let mut inside: Vec<Clip> = Vec::with_capacity(selected.len());
        for clip in &selected {
            let Some((_, track)) = mapping.iter().find(|(from, _)| *from == clip.track) else {
                continue;
            };
            let mut moved = clip.clone();
            moved.track = *track;
            moved.start = clip.start.saturating_sub(earliest);
            inside.push(moved);
        }
        // Any sound inside means the nest clip needs a volume of its own to
        // scale it by; a nest of text and shapes gets no audio group, so the
        // inspector shows no Audio tab for something that cannot make a
        // sound.
        let audible = inside.iter().any(|c| c.audio.is_some());

        next.clips
            .retain(|c| !selected.iter().any(|s| s.id == c.id));
        next.nests.push(Nest {
            id: nest_id,
            name: match name.map(str::trim).filter(|n| !n.is_empty()) {
                Some(given) => given.to_string(),
                None => format!("Nest {}", next.nests.len().saturating_add(1)),
            },
            width: next.canvas.width,
            height: next.canvas.height,
            tracks,
            clips: inside,
        });

        let clip_id = next.allocate_id();
        // A transition INTO the selection belonged to a clip that is now
        // inside the group, so the nest clip gets the default cross
        // dissolve over whatever overlap it inherits — the same rule
        // every other op uses for a clip that gains one.
        next.clips.push(Clip {
            video: Some(VideoProps::default()),
            audio: audible.then(AudioProps::default),
            ..Clip::placed(
                clip_id,
                front_track,
                earliest,
                latest.saturating_sub(earliest),
                Source::Nest { project: nest_id },
            )
        });

        if let Err(why) = next.check_overlap_rule(&[], front_track, &[]) {
            return Ok(Outcome::Refused(why));
        }
        self.finish_placement(next, &[front_track])
    }

    /// Puts a nest clip's contents back on the timeline and removes the clip
    /// (spec §6) — the inverse of [`Project::nest_clips`].
    ///
    /// Each clip returns at `clip.start + its own start`, with fresh ids, on
    /// the track counted back from the nest clip's own: the nest's
    /// front-most NON-matte track (the front-most when all are, MT-5) lands
    /// where the nest clip was, the one behind it a track further back, a
    /// carried matte track in front of it a track further forward, and
    /// tracks missing behind are added. A clip the overlap rule refuses —
    /// or a matte clip with no track in front — goes on a new track in
    /// front, ordinary: `unnest` makes no track a matte.
    ///
    /// The nest itself is dropped when nothing else shows it; a second clip
    /// showing it keeps it, which is why the returned clips are copies.
    /// `Err` when `clip` is not a nest clip.
    pub fn unnest_clip(&self, clip: u32) -> Result<Outcome, String> {
        let target = self.require_clip(clip)?.clone();
        let Source::Nest { project } = target.source else {
            return Err(format!("clip {clip} is not a nest clip"));
        };
        // `validate` refuses a clip pointing at a nest that is not there, so
        // this is a corrupt project rather than a caller's mistake — an
        // error either way, naming both ids.
        let nest = self
            .nest(project)
            .ok_or_else(|| format!("clip {clip} shows unknown nest {project}"))?
            .clone();

        let base = self.require_track_index(target.track)? as i64;
        // The nest's front-most non-matte track, the one the nest clip's own
        // track stands for (MT-5); the front-most when all are mattes.
        let front = nest
            .tracks
            .iter()
            .rposition(|t| t.matte.is_none())
            .unwrap_or(nest.tracks.len().saturating_sub(1)) as i64;
        let depth = |track: u32| -> i64 {
            // 0 for `front`, counting backwards; negative for a carried
            // matte track in front of it.
            match nest.tracks.iter().position(|t| t.id == track) {
                Some(index) => front - index as i64,
                None => 0,
            }
        };
        // Bounded by the track cap the project was read under, so the
        // deficit loop below can ask for at most `MAX_TRACKS` tracks and
        // `finish` refuses the result if that is too many.
        let deepest = front;

        let mut next = self.clone();
        next.clips.retain(|c| c.id != clip);

        // Tracks missing behind the destination, exactly as `paste` adds
        // them: inserting at index 0 shifts every existing track up, so the
        // destination index moves with them.
        let base = next.add_tracks_behind(deepest, base);

        // Back-most first, then time: the order clips are placed in is the
        // order the overlap rule sees them, so it has to be deterministic or
        // one nest could open two ways.
        let mut ordered: Vec<&Clip> = nest.clips.iter().collect();
        ordered.sort_by_key(|c| (std::cmp::Reverse(depth(c.track)), c.start, c.id));

        let mut landing = Landing::new(base);
        let first = next.clips.len();
        let mut fresh: HashMap<u32, u32> = HashMap::new();
        for source in ordered {
            let mut moved = source.clone();
            next.remint(&mut moved);
            fresh.insert(source.id, moved.id);
            // Translate first; the shared normalization then handles a
            // hand-written or legacy off-grid nest on the parent grid.
            moved.start = target.start.saturating_add(source.start);
            next.resnap_clip_times(&mut moved);
            landing.land(&mut next, moved, depth(source.track));
        }
        // The returning clips re-pair through their fresh ids (AU-96).
        if let Some(landed) = next.clips.get_mut(first..) {
            relink_copies(landed, &fresh);
        }

        if !next.nest_is_shown(project) {
            next.nests.retain(|n| n.id != project);
        }
        self.finish_placement(next, landing.touched())
    }
}

import AVFoundation
import CoreVideo
import Metal

/// The matte pass (spec §11 MT-3, MT-6): every matte the recipe lists drawn
/// into a destination-sized target BEFORE the destination pass opens, and
/// each distinct set of mattes a layer is cut by resolved into one
/// destination-sized `r8Unorm` coverage, which the layer stage samples at
/// `texture(1)`. Split out of `Compositor.swift` for size, as
/// `Compositor+Shadow.swift` was; `render` calls `encodeMattes` once per
/// frame and reads its answer per layer.
///
/// A matte never suspends the destination pass, the way a shadow does: it is
/// all encoded before that pass opens, deepest container first (the order
/// the recipe lists them in), so a layer drawn into an outer matte can
/// already be cut by an inner one.

/// The matte resolve pass's uniform block, mirroring `MatteUniforms` in
/// `Compositor.metal` FIELD FOR FIELD under `LayerUniforms`' layout
/// contract: scalars only, a multiple of 16 bytes.
struct MatteUniforms {
    /// A `TrackMatte.shaderCode`.
    var mode: Float = 0
    /// 1 in an HLG project: a luma matte reads the un-lifted colour (spec
    /// §11 HD-13 (h)); 0 in an SDR project.
    var hlgOutput: Float = 0
    /// 1 when the canvas blends in linear light: a luma matte reads the
    /// encoded colour of its linear composite (spec §11 HD-16 (e)).
    var linearLight: Float = 0
    var reserved2: Float = 0
}

/// Why a matted frame could not be composed.
enum MatteError: LocalizedError {
    case noTarget
    /// A layer is cut by a matte that is not drawn before it is needed. A
    /// recipe from the core never says so — the list is deepest container
    /// first and a matte track is nobody's target (MT-2) — so it fails the
    /// frame rather than draw a picture the recipe did not describe.
    case unordered

    var errorDescription: String? {
        switch self {
        case .noTarget: return "A matte's offscreen target could not be made."
        case .unordered: return "A layer is cut by a matte that is not drawn before it."
        }
    }
}

/// The destination-sized targets the matte pass draws into (spec §11 MT-6,
/// MT-9): at 3840×2160, 66.4 MB per matte composite and 8.3 MB per coverage.
/// A frame is one `render` call, bracketed by `beginFrame` and `endFrame`.
/// Within it a composite is taken and given back as `MattePlan` says, so a
/// later matte draws into one an earlier matte no longer needs; a coverage is
/// the `index`th cut set's and outlives the destination pass. Between frames
/// the pool keeps, of each kind, the most any of the last `keepFrames` frames
/// held at once, and releases the rest when a frame ends. A frame that needs
/// more targets gets them. A routed dissolve's two halves take composites
/// from the same pool (MT-8, `Compositor+Dissolve.swift`). Emptied when the
/// destination size changes. One
/// renderer serves one serial render queue and waits for each frame's GPU
/// work, so every target is free again by the next frame.
final class MattePool {
    /// How many frames, the current one included, the pool's size answers to.
    static let keepFrames = 30

    private let device: MTLDevice
    private var width = 0
    private var height = 0
    private var composites: [MTLTexture] = []
    /// Per composite, whether this frame holds it.
    private var taken: [Bool] = []
    private var coverages: [MTLTexture] = []
    /// What this frame has held at once: composites, coverages.
    private var peak = (composites: 0, coverages: 0)
    /// `peak` of each of the last `keepFrames` frames, oldest first.
    private var recent: [(composites: Int, coverages: Int)] = []

    init(device: MTLDevice) {
        self.device = device
    }

    @available(*, unavailable) required init?(coder: NSCoder) {
        fatalError("MattePool does not support NSCoder")
    }

    /// Starts a frame `width` × `height`: a size change drops every target,
    /// and every composite is free.
    func beginFrame(width: Int, height: Int) {
        if width != self.width || height != self.height {
            self.width = width
            self.height = height
            composites = []
            coverages = []
        }
        taken = Array(repeating: false, count: composites.count)
        peak = (0, 0)
    }

    /// A free composite target, premultiplied, in the working format
    /// (`rgba16Float`, spec §11 PR-1): the lowest free index, made when none
    /// is free. Nil only when Metal cannot make one.
    func takeComposite() -> MTLTexture? {
        let index: Int
        if let free = taken.firstIndex(of: false) {
            index = free
        } else {
            guard let made = makeTarget(format: MetalRenderer.workingFormat) else { return nil }
            composites.append(made)
            taken.append(false)
            index = composites.count - 1
        }
        taken[index] = true
        peak.composites = max(peak.composites, taken.filter { $0 }.count)
        return composites[index]
    }

    /// Gives `texture` back to this frame's free composites.
    func giveComposite(_ texture: MTLTexture) {
        guard let index = composites.firstIndex(where: { $0 === texture }) else { return }
        taken[index] = false
    }

    /// The `index`th coverage target, one channel.
    func coverage(_ index: Int) -> MTLTexture? {
        while coverages.count <= index {
            guard let made = makeTarget(format: .r8Unorm) else { return nil }
            coverages.append(made)
        }
        peak.coverages = max(peak.coverages, index + 1)
        return coverages[index]
    }

    /// Ends the frame: keeps, of each kind, the most any of the last
    /// `keepFrames` frames held, and releases the targets past it.
    func endFrame() {
        recent.append(peak)
        let window = MattePool.keepFrames
        if recent.count > window { recent.removeFirst(recent.count - window) }
        trim(&composites, to: recent.map(\.composites).max() ?? 0)
        trim(&coverages, to: recent.map(\.coverages).max() ?? 0)
        taken = Array(repeating: false, count: composites.count)
        peak = (0, 0)
    }

    /// The targets the pool holds now: composites, coverages.
    var held: (composites: Int, coverages: Int) {
        (composites.count, coverages.count)
    }

    private func trim(_ list: inout [MTLTexture], to count: Int) {
        if list.count > count { list.removeLast(list.count - count) }
    }

    private func makeTarget(format: MTLPixelFormat) -> MTLTexture? {
        let descriptor = MTLTextureDescriptor.texture2DDescriptor(
            pixelFormat: format, width: max(1, width), height: max(1, height),
            mipmapped: false)
        descriptor.usage = [.renderTarget, .shaderRead]
        descriptor.storageMode = .private
        return device.makeTexture(descriptor: descriptor)
    }
}

/// What the matte pass answers: the coverage each layer's fragment stage
/// samples at `texture(1)`.
struct MatteCoverage {
    let placeholder: MTLTexture
    fileprivate(set) var byCut: [[Int]: MTLTexture] = [:]

    init(placeholder: MTLTexture) {
        self.placeholder = placeholder
    }

    /// The layer's coverage: the 1×1 white placeholder for a layer no matte
    /// cuts (MT0's route), the resolved product for one that is cut, and nil
    /// only for a cut set the pass did not resolve — which a recipe from the
    /// core never asks for, and `render` fails the frame on (`unordered`).
    func texture(for layer: RecipeLayer) -> MTLTexture? {
        guard let cut = layer.matte?.cut, !cut.isEmpty else { return placeholder }
        return byCut[cut]
    }
}

extension MetalRenderer {

    /// The resolve pipeline: the shadow pass's full-frame quad and
    /// `framejob_matte_resolve_fragment`, into `r8Unorm`, with source factor
    /// ZERO and destination factor `sourceColor` — the coverage is cleared
    /// to 1 and each matte's value multiplies into it.
    static func matteResolveDescriptor(
        vertex: MTLFunction, fragment: MTLFunction
    ) -> MTLRenderPipelineDescriptor {
        let descriptor = MTLRenderPipelineDescriptor()
        descriptor.label = "Frame Job matte resolve"
        descriptor.vertexFunction = vertex
        descriptor.fragmentFunction = fragment
        descriptor.colorAttachments[0].pixelFormat = .r8Unorm
        descriptor.colorAttachments[0].isBlendingEnabled = true
        descriptor.colorAttachments[0].rgbBlendOperation = .add
        descriptor.colorAttachments[0].alphaBlendOperation = .add
        descriptor.colorAttachments[0].sourceRGBBlendFactor = .zero
        descriptor.colorAttachments[0].sourceAlphaBlendFactor = .zero
        descriptor.colorAttachments[0].destinationRGBBlendFactor = .sourceColor
        descriptor.colorAttachments[0].destinationAlphaBlendFactor = .sourceColor
        return descriptor
    }

    /// Encodes every matte `recipe.mattes` lists into `buffer`, ahead of the
    /// destination pass, and resolves the coverage of every layer that a
    /// matte cuts, in the order `MattePlan` gives (spec §11 MT-9). A layer
    /// whose `into` names a group is drawn into that group's composite with
    /// the ordinary layer pipelines, so every one of its own properties
    /// shapes the matte (MT-4); it is never drawn on the canvas, which
    /// `render` decides. A cut set the plan never resolves stays nil, and
    /// `render` fails the frame on it (`unordered`).
    func encodeMattes(
        recipe: FrameRecipe, canvas: RecipeCanvas, target: MTLTexture,
        buffer: MTLCommandBuffer, request: AVAsynchronousVideoCompositionRequest,
        instruction: RecipeInstruction?, live: inout [CVMetalTexture]
    ) throws -> MatteCoverage {
        var coverage = MatteCoverage(placeholder: placeholder)
        guard !recipe.mattes.isEmpty else { return coverage }
        let plan = MattePlan(
            groups: recipe.mattes.map(\.group),
            cuts: recipe.layers.compactMap { layer in
                guard let cut = layer.matte?.cut, !cut.isEmpty else { return nil }
                return cut
            })
        var composites: [Int: (texture: MTLTexture, mode: TrackMatte)] = [:]

        for (group, step) in zip(recipe.mattes, plan.steps) {
            let members = recipe.layers.filter { $0.matte?.into == step.group }
            // Each member's coverage, resolved at an earlier step — the list
            // is deepest container first — and checked before the pass opens:
            // a throw never leaves an encoder open.
            guard members.allSatisfy({ coverage.texture(for: $0) != nil }) else {
                throw MatteError.unordered
            }
            guard let composite = mattePool.takeComposite() else { throw MatteError.noTarget }
            // A pass of its own, cleared transparent, drawn exactly as the
            // destination pass draws its layers (`encodeLayers`) — a shadow
            // suspends it the same way, and a routed dissolve among the
            // members is two halves mixed here (MT-8) — so nothing on this
            // side has an opinion about a matte layer's blend, shadow or
            // reflection: the core cleared them.
            var pass = DestinationPass(
                buffer: buffer, target: composite,
                clear: MTLClearColor(red: 0, green: 0, blue: 0, alpha: 0),
                pipeline: pipeline, sampler: sampler)
            guard pass.open() != nil else { throw MatteError.noTarget }
            try encodeLayers(
                members, depth: 0, among: recipe.layers, coverage: coverage, canvas: canvas,
                pass: &pass, request: request, instruction: instruction, live: &live)
            pass.suspend()
            composites[step.group] = (composite, group.mode)
            for cut in step.resolve {
                try resolve(
                    cut, composites, into: &coverage, buffer, hlg: canvas.output == .hlg,
                    linear: canvas.blending == .linear)
            }
            // A composite no later resolve reads goes back to the pool, so the
            // next step may draw into it; Metal orders that clear after the
            // resolves above, which read it, in this one command buffer.
            for released in step.release {
                if let given = composites.removeValue(forKey: released) {
                    mattePool.giveComposite(given.texture)
                }
            }
        }
        return coverage
    }

    /// One cut set's coverage, resolved once per frame: a pass cleared to 1
    /// with each matte's mode multiplied in. An empty set is the placeholder
    /// and encodes nothing. `hlg`: an HLG project's luma reads the un-lifted
    /// colour (spec §11 HD-13 (h)); `linear`: a linear canvas's luma reads
    /// the encoded colour (HD-16 (e)).
    private func resolve(
        _ cut: [Int], _ composites: [Int: (texture: MTLTexture, mode: TrackMatte)],
        into coverage: inout MatteCoverage, _ buffer: MTLCommandBuffer, hlg: Bool,
        linear: Bool
    ) throws {
        guard !cut.isEmpty, coverage.byCut[cut] == nil else { return }
        // Every matte in the set is drawn already, checked before the pass
        // opens so that a throw never leaves an encoder open.
        let mattes: [(texture: MTLTexture, mode: TrackMatte)] = try cut.map {
            guard let matte = composites[$0] else { throw MatteError.unordered }
            return matte
        }
        guard let texture = mattePool.coverage(coverage.byCut.count) else {
            throw MatteError.noTarget
        }
        let descriptor = MTLRenderPassDescriptor()
        descriptor.colorAttachments[0].texture = texture
        descriptor.colorAttachments[0].loadAction = .clear
        descriptor.colorAttachments[0].storeAction = .store
        descriptor.colorAttachments[0].clearColor = MTLClearColor(
            red: 1, green: 1, blue: 1, alpha: 1)
        guard let encoder = buffer.makeRenderCommandEncoder(descriptor: descriptor) else {
            throw MatteError.noTarget
        }
        encoder.setRenderPipelineState(matteResolvePipeline)
        for matte in mattes {
            var u = MatteUniforms()
            u.mode = matte.mode.shaderCode
            u.hlgOutput = hlg ? 1 : 0
            u.linearLight = linear ? 1 : 0
            encoder.setFragmentBytes(&u, length: MemoryLayout<MatteUniforms>.stride, index: 0)
            encoder.setFragmentTexture(matte.texture, index: 0)
            encoder.drawPrimitives(type: .triangleStrip, vertexStart: 0, vertexCount: 4)
        }
        encoder.endEncoding()
        coverage.byCut[cut] = texture
    }
}
