//! The transitions a layer plays at one instant (spec §7.3, §11 MT-8): each
//! recipe layer's `transition` and `dissolve`.
//!
//! A layer inside `n` nest clips has `n + 1` LEVELS, walked inner to outer:
//! its own clip in the innermost container, then each enclosing nest clip in
//! ITS container, outward to the timeline. Each level asks
//! [`transition::transition_among`] — the one transition lookup — at that
//! container's own time.
//!
//! ### Routed and unrouted
//!
//! A `cross_dissolve` or `zoom` whose container is a nest, or one of whose
//! two clips is a nest clip, is ROUTED ([`routed`], the one predicate): the
//! compositor draws each half alone into a target of its own and mixes the
//! two (§7.5), because a half that is more than one layer — or a layer that
//! is not on the canvas, a nest clip — cannot carry the per-layer weight
//! correction a timeline pair does (MT-3). A routed level is an entry in the
//! layer's `dissolve`, never its `transition`; `transition` is the innermost
//! level's answer that is NOT routed, as `recipe.rs`'s `transition_of`
//! answered every kind before issue batch B90 moved its walk here. A push,
//! slide, wipe or fade is never routed: none applies a partner correction.
//!
//! ### The contract the compositor relies on
//!
//! `dissolve` is `null` or the routed levels, OUTERMOST first, each
//! `{id, kind, role, progress, anchor}`. A dissolve is one [`DissolveKey`]:
//! the nest clips enclosing its container, its earlier clip and its later
//! clip, so two clips showing one nest at one instant each have their own.
//! Ids are dense from 0 in first-seen order, walking layers back to front,
//! each chain outermost first. `anchor` is the canvas point (top-left frame)
//! the half is placed at: the layer's own anchor at its own level, the
//! centre of the nest's placed canvas rectangle at a nest clip's. A layer
//! drawn into a matte keeps only the routed levels at or inside its first
//! matte level — the matte is drawn whole, and the half it lies in fades it
//! once — while its `transition` is still sought outward.

use serde_json::{Map, Value};

use crate::evaluate::{json, number};
use crate::model::{Clip, Project, Source, TransitionKind};
use crate::nest::Instance;
use crate::time::Ticks;
use crate::transition;

/// One routed dissolve at one instant: the ids of the nest clips enclosing
/// its container, outermost first — an instance path's prefix — and its two
/// clips.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct DissolveKey {
    pub path: Vec<u32>,
    pub earlier: u32,
    pub later: u32,
}

/// What [`Project::frame_transitions`] answers: per instance, in the order
/// given, the layer's `transition` and its `dissolve`.
pub(crate) struct FrameTransitions {
    pub transition: Vec<Value>,
    pub dissolve: Vec<Value>,
}

/// Whether a transition is ROUTED (spec §11 MT-8): a `cross_dissolve` or a
/// `zoom` whose container is a nest (`in_nest`), or one of whose two clips is
/// a nest clip. `partner` is `None` when the container does not hold it.
pub(crate) fn routed(
    in_nest: bool,
    kind: TransitionKind,
    clip: &Clip,
    partner: Option<&Clip>,
) -> bool {
    let is_nest = |c: &Clip| matches!(c.source, Source::Nest { .. });
    let mixed = matches!(kind, TransitionKind::CrossDissolve | TransitionKind::Zoom);
    let nested = in_nest || is_nest(clip) || partner.is_some_and(is_nest);
    mixed && nested
}

/// One routed level before ids are given.
struct Routed {
    key: DissolveKey,
    kind: TransitionKind,
    progress: f64,
    incoming: bool,
    anchor: (f64, f64),
}

impl Project {
    /// The transitions at the instant `instances` cover (spec §7.3): one
    /// `transition` and one `dissolve` per instance, in their order. See the
    /// module doc for the contract.
    pub(crate) fn frame_transitions(
        &self,
        instances: &[Instance<'_>],
        t: Ticks,
    ) -> FrameTransitions {
        let walked: Vec<(Value, Vec<Routed>)> = instances
            .iter()
            .map(|i| self.transition_levels(i, t))
            .collect();

        let mut keys: Vec<DissolveKey> = Vec::new();
        let mut id_of = |key: &DissolveKey| -> usize {
            match keys.iter().position(|k| k == key) {
                Some(found) => found,
                None => {
                    keys.push(key.clone());
                    keys.len() - 1
                }
            }
        };

        let mut transition = Vec::with_capacity(walked.len());
        let mut dissolve = Vec::with_capacity(walked.len());
        for (found, chain) in walked {
            transition.push(found);
            dissolve.push(if chain.is_empty() {
                Value::Null
            } else {
                Value::Array(
                    chain
                        .iter()
                        .map(|level| dissolve_entry(id_of(&level.key), level))
                        .collect(),
                )
            });
        }
        FrameTransitions {
            transition,
            dissolve,
        }
    }

    /// One layer's levels walked inner to outer: its `transition` (the
    /// innermost unrouted answer) and its routed levels, outermost first.
    fn transition_levels(&self, instance: &Instance<'_>, t: Ticks) -> (Value, Vec<Routed>) {
        // A container's own time base: its zero sits at `origin - start`, so
        // this maps project time onto it for any clip in it.
        let local =
            |clip: &Clip, origin: Ticks| t.saturating_sub(origin).saturating_add(clip.start);

        let depth = instance.inside.len();
        let mut transition = Value::Null;
        let mut chain = Vec::new();
        let mut stopped = false;
        for level in (0..=depth).rev() {
            let (clip, origin, track) = if level == depth {
                (instance.clip, instance.origin, instance.track)
            } else {
                match instance.inside.get(level) {
                    Some(enclosing) => (enclosing.clip, enclosing.origin, enclosing.track),
                    None => break,
                }
            };
            let container: &[Clip] = match level.checked_sub(1) {
                Some(up) => match instance.inside.get(up) {
                    Some(enclosing) => &enclosing.nest.clips,
                    None => break,
                },
                None => &self.clips,
            };
            if let Some((kind, progress, incoming, partner)) =
                transition::transition_among(container, clip.id, local(clip, origin))
            {
                let other = container.iter().find(|c| c.id == partner);
                if routed(level > 0, kind, clip, other) {
                    if !stopped {
                        let path = instance.inside.iter().take(level).map(|e| e.clip.id);
                        let (earlier, later) = if incoming {
                            (partner, clip.id)
                        } else {
                            (clip.id, partner)
                        };
                        chain.push(Routed {
                            key: DissolveKey {
                                path: path.collect(),
                                earlier,
                                later,
                            },
                            kind,
                            progress,
                            incoming,
                            anchor: self.half_anchor(instance, level, t),
                        });
                    }
                } else if transition.is_null() {
                    transition = transition_entry(kind, progress, incoming, partner);
                }
            }
            // The first matte level ends the routed walk (MT-8): what is
            // drawn into a matte is drawn whole.
            if !track.matte.is_none() {
                stopped = true;
            }
        }
        chain.reverse();
        (transition, chain)
    }

    /// The canvas point (top-left frame) the half at `level` is placed at:
    /// the layer's own anchor at its own level, else the centre of the clip
    /// rectangle the nest clip at `level` gives its contents.
    fn half_anchor(&self, instance: &Instance<'_>, level: usize, t: Ticks) -> (f64, f64) {
        let width = f64::from(self.canvas.width);
        let height = f64::from(self.canvas.height);
        if level >= instance.inside.len() {
            let placed = self.placement(instance, t);
            return (width / 2.0 + placed.x, height / 2.0 + placed.y);
        }
        let mut entered = instance.clone();
        entered.inside.truncate(level + 1);
        match self.frame_of(&entered, t).clip_rect {
            Some(rect) => (rect.x, rect.y),
            None => (width / 2.0, height / 2.0),
        }
    }
}

/// A layer's `transition` object: `{kind, progress, role, partner}`.
fn transition_entry(kind: TransitionKind, progress: f64, incoming: bool, partner: u32) -> Value {
    let mut entry = Map::new();
    entry.insert("kind".to_string(), json(&kind));
    entry.insert("progress".to_string(), number(progress));
    entry.insert("role".to_string(), Value::from(role(incoming)));
    entry.insert("partner".to_string(), Value::from(partner));
    Value::Object(entry)
}

/// One `dissolve` entry: `{id, kind, role, progress, anchor}`.
fn dissolve_entry(id: usize, level: &Routed) -> Value {
    let mut entry = Map::new();
    entry.insert("id".to_string(), Value::from(id));
    entry.insert("kind".to_string(), json(&level.kind));
    entry.insert("role".to_string(), Value::from(role(level.incoming)));
    entry.insert("progress".to_string(), number(level.progress));
    entry.insert(
        "anchor".to_string(),
        Value::Array(vec![number(level.anchor.0), number(level.anchor.1)]),
    );
    Value::Object(entry)
}

fn role(incoming: bool) -> &'static str {
    if incoming {
        "in"
    } else {
        "out"
    }
}
import AVFoundation
import CoreVideo
import Metal

/// The routed dissolve (spec §11 MT-8, §7.5): a `cross_dissolve` or `zoom`
/// with a nested half — a layer's `dissolve`, which the core decides — is
/// drawn as two halves, each alone and unweighted into a destination-sized
/// pool target cleared transparent, then laid on the pass in one full-frame
/// draw as (1 − p)·out + p·in, a zoom's halves scaled there about their
/// anchors. `encodeLayers` is the one walk over a layer list both passes
/// make — the canvas's in `render` and a matte group's members in
/// `encodeMattes` — and `drawLayer` the one per-layer draw under it, so a
/// half is everything its layers draw: shadows, reflections, mattes cutting
/// it, and any routed dissolve inside it, one level deeper.
///
/// A timeline pair of clips that are not nest clips is not routed and keeps
/// the per-layer weight correction (MT-3); a frame with no routed dissolve
/// takes no target and draws exactly as before.

/// The dissolve mix's uniform block, mirroring `DissolveUniforms` in
/// `Compositor.metal` FIELD FOR FIELD under `LayerUniforms`' layout
/// contract: scalars only, 12 floats, 48 bytes.
struct DissolveUniforms {
    var progress: Float = 0
    /// 1 for a routed zoom, whose halves the mix scales.
    var zoom: Float = 0
    var canvasPerDestX: Float = 1
    var canvasPerDestY: Float = 1
    var canvasWidth: Float = 0
    var canvasHeight: Float = 0
    /// Canvas pixels, top-left frame.
    var outAnchorX: Float = 0
    var outAnchorY: Float = 0
    var inAnchorX: Float = 0
    var inAnchorY: Float = 0
    var reserved0: Float = 0
    var reserved1: Float = 0
}

/// Why a routed dissolve could not be composed.
enum DissolveError: LocalizedError {
    case noTarget

    var errorDescription: String? {
        switch self {
        case .noTarget: return "A dissolve's offscreen half could not be made."
        }
    }
}

extension MetalRenderer {

    /// Draws `layers`, back to front, onto `pass`. A run of layers that are
    /// halves of one routed dissolve at chain depth `depth` — contiguous,
    /// out before in, as the core lists them — is drawn as two halves and
    /// mixed (`encodeDissolve`); every other layer is drawn as it stands.
    /// `all` is the recipe's whole layer list, where a transition's partner
    /// is looked up. Every throw leaves every pass it opened, and `pass`,
    /// suspended.
    func encodeLayers(
        _ layers: [RecipeLayer], depth: Int, among all: [RecipeLayer],
        coverage: MatteCoverage, canvas: RecipeCanvas, pass: inout DestinationPass,
        request: AVAsynchronousVideoCompositionRequest, instruction: RecipeInstruction?,
        live: inout [CVMetalTexture]
    ) throws {
        let destination = CGSize(width: pass.target.width, height: pass.target.height)
        var index = 0
        while index < layers.count {
            let layer = layers[index]
            guard layer.dissolve.count > depth else {
                index += 1
                // An adjustment clip grades what is behind it rather than
                // drawing a picture (spec §11 GR-6, `Compositor+Adjustment.swift`).
                if layer.isAdjustment {
                    guard let matte = coverage.texture(for: layer) else {
                        pass.suspend()
                        throw MatteError.unordered
                    }
                    try drawAdjustment(
                        layer, matte: matte, canvas: canvas,
                        urls: RecipeSource.shared.lookURLs(for: instruction), pass: &pass)
                    continue
                }
                guard
                    let prepared = prepare(
                        layer, among: all, canvas: canvas, destination: destination,
                        request: request, instruction: instruction, live: &live)
                else { continue }
                // The mattes cutting this layer, or the placeholder (MT-3).
                guard let matte = coverage.texture(for: layer) else {
                    pass.suspend()
                    throw MatteError.unordered
                }
                try drawLayer(layer, prepared, matte: matte, canvas: canvas, pass: &pass)
                continue
            }
            let id = layer.dissolve[depth].id
            var end = index + 1
            while end < layers.count, layers[end].dissolve.count > depth,
                layers[end].dissolve[depth].id == id
            {
                end += 1
            }
            try encodeDissolve(
                Array(layers[index..<end]), depth: depth, among: all, coverage: coverage,
                canvas: canvas, pass: &pass, request: request, instruction: instruction,
                live: &live)
            index = end
        }
    }

    /// One routed dissolve: `block` split by role at `depth`, each half drawn
    /// into its own pool target (even an empty half, cleared), then the two
    /// mixed onto `pass` with `dissolvePipeline`.
    private func encodeDissolve(
        _ block: [RecipeLayer], depth: Int, among all: [RecipeLayer],
        coverage: MatteCoverage, canvas: RecipeCanvas, pass: inout DestinationPass,
        request: AVAsynchronousVideoCompositionRequest, instruction: RecipeInstruction?,
        live: inout [CVMetalTexture]
    ) throws {
        let halves = [
            block.filter { !$0.dissolve[depth].isIncoming },
            block.filter { $0.dissolve[depth].isIncoming },
        ]
        pass.suspend()
        guard let outgoing = mattePool.takeComposite() else { throw DissolveError.noTarget }
        defer { mattePool.giveComposite(outgoing) }
        guard let incoming = mattePool.takeComposite() else { throw DissolveError.noTarget }
        defer { mattePool.giveComposite(incoming) }
        // Metal orders each target's clear after any earlier read of it in
        // this command buffer: a pool target is hazard-tracked (MT-9).
        for (half, target) in zip(halves, [outgoing, incoming]) {
            var drawn = DestinationPass(
                buffer: pass.buffer, target: target,
                clear: MTLClearColor(red: 0, green: 0, blue: 0, alpha: 0),
                pipeline: pipeline, sampler: sampler)
            guard drawn.open() != nil else { throw DissolveError.noTarget }
            defer { drawn.suspend() }
            try encodeLayers(
                half, depth: depth + 1, among: all, coverage: coverage, canvas: canvas,
                pass: &drawn, request: request, instruction: instruction, live: &live)
        }

        guard let encoder = pass.open() else { throw DissolveError.noTarget }
        let entry = block[0].dissolve[depth]
        var u = DissolveUniforms()
        u.progress = Float(min(max(entry.progress, 0), 1))
        u.zoom = entry.kind == .zoom ? 1 : 0
        u.canvasWidth = Float(max(1, canvas.width))
        u.canvasHeight = Float(max(1, canvas.height))
        u.canvasPerDestX = u.canvasWidth / Float(max(1, pass.target.width))
        u.canvasPerDestY = u.canvasHeight / Float(max(1, pass.target.height))
        // Each half's anchor from its first layer; an empty half draws
        // nothing, so its anchor is never read.
        if let anchor = halves[0].first?.dissolve[depth].anchor, anchor.count >= 2 {
            u.outAnchorX = Float(anchor[0])
            u.outAnchorY = Float(anchor[1])
        }
        if let anchor = halves[1].first?.dissolve[depth].anchor, anchor.count >= 2 {
            u.inAnchorX = Float(anchor[0])
            u.inAnchorY = Float(anchor[1])
        }
        encoder.setRenderPipelineState(dissolvePipeline)
        encoder.setFragmentBytes(&u, length: MemoryLayout<DissolveUniforms>.stride, index: 0)
        encoder.setFragmentTexture(outgoing, index: 0)
        encoder.setFragmentTexture(incoming, index: 1)
        encoder.drawPrimitives(type: .triangleStrip, vertexStart: 0, vertexCount: 4)
        // Back to the pass's own pipeline, so the next layer inherits the
        // state `DestinationPass.open()` promises.
        encoder.setRenderPipelineState(pass.pipeline)
    }

    /// One layer drawn onto `pass`: its shadow, then its reflection and
    /// itself, `texture(1)` bound to the mattes cutting it. A layer that
    /// needs a neighbourhood filter or a blend mode takes its own pipeline
    /// state for the draw (`pipelineState(gather:blend:)`), its shadow's
    /// mask the same specialization without the blend. A layer whose `blur`
    /// lists samples is drawn at each of them instead (spec §11 CU-117,
    /// `Compositor+MotionBlur.swift`).
    func drawLayer(
        _ layer: RecipeLayer, _ prepared: PreparedLayer, matte: MTLTexture,
        canvas: RecipeCanvas, pass: inout DestinationPass
    ) throws {
        if let blur = layer.blur, !blur.samples.isEmpty {
            try drawBlurred(
                layer, prepared, blur: blur, matte: matte, canvas: canvas, pass: &pass)
